import { useState } from "react";

export function ContextualHelp({
  label = "{{label}}",
  helpText = "{{helpText}}",
  expanded: initialExpanded = {{expanded}},
  variant = "{{variant}}",
  accent = "{{accent}}",
}) {
  const [expanded, setExpanded] = useState(initialExpanded);
  const panelStyle = {
    tooltip: { background: "#241430", color: "#FAF7F2", padding: "10px 12px", borderRadius: 8 },
    inline: { paddingLeft: 21, borderLeft: "2px solid " + accent },
    callout: { background: accent, color: "#241430", padding: "12px 14px", borderRadius: 10 },
  }[variant] ?? {};
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 16, lineHeight: 1.5, color: "#241430", maxWidth: 320 }}>
      <button type="button" aria-expanded={expanded} aria-describedby="ch-help-text-react" onClick={() => setExpanded((e) => !e)}
        style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "transparent", border: "none", padding: "4px 0", font: "600 14px system-ui, sans-serif", color: accent, cursor: "pointer" }}>
        <span>{label}</span>
        <svg width="15" height="15" viewBox="0 0 16 16" fill="none" aria-hidden="true"><circle cx="8" cy="8" r="7" stroke="currentColor" strokeWidth="1.3" /><path d="M8 7v4.5M8 4.6v.1" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" /></svg>
      </button>
      {expanded && (
        <div id="ch-help-text-react" style={{ marginTop: 8, fontSize: 13.5, ...panelStyle }}>{helpText}</div>
      )}
    </div>
  );
}
